$checks=0;function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);++$checks;echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Verein A'),('b','Verein B');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1),('paul','a','member',1),('wilma','a','member',0),('hartmut','a','member',0),('klaus','a','member',0),('member','a','member',0),('foreign','b','members',0),('editor','a','editor',0)");
