$board=new AdmissionVotes($db,'admin');foreach(['paul'=>'1. Vorstand','wilma'=>'2. Vorstand','hartmut'=>'Kassenwart','klaus'=>'Schriftwart'] as $id=>$office)$board->grant($id,0,$office,true,true);
$routes=['home'=>['view'=>'dashboard'],'members'=>['view'=>'members'],'contacts'=>['view'=>'members','list'=>'contacts'],'finance'=>['view'=>'finance'],'donations'=>['view'=>'donations'],'assets'=>['view'=>'inventory','tab'=>'assets'],'inventory'=>['view'=>'inventory'],'own'=>['view'=>'portal','tab'=>'own'],'material'=>['view'=>'material'],'loans'=>['view'=>'inventory','tab'=>'loans'],'free'=>['view'=>'free'],'minutes'=>['view'=>'minutes'],'calendar'=>['view'=>'calendar'],'press'=>['view'=>'website','tab'=>'press'],'website_pages'=>['view'=>'website','tab'=>'pages'],'roles'=>['view'=>'settings','tab'=>'roles'],'admissions'=>['view'=>'portal','tab'=>'application'],'documents'=>['view'=>'documents']];
$base=['home','own','free','minutes','calendar'];
$expect=['member'=>$base,'klaus'=>array_merge($base,['press','admissions','documents']),'hartmut'=>array_merge($base,['members','contacts','finance','donations','assets','admissions','documents']),'wilma'=>array_keys($routes),'admin'=>array_keys($routes),'paul'=>array_keys($routes)];
foreach($expect as $actor=>$keys){$access=new WorkspaceAccess($db,$actor);foreach($routes as $key=>$route)check($access->allows($route)===in_array($key,$keys,true),$actor.' route '.$key);}
$memberAccess=new WorkspaceAccess($db,'member');check($memberAccess->allows(['view'=>'members','id'=>$own]),'own member detail allowed');check(!$memberAccess->allows(['view'=>'members','id'=>$other]),'foreign member detail denied');
check(count((new Registry($db,'member'))->contacts())===1,'member service returns own contact only');denied(fn()=>(new Registry($db,'member'))->contact($other),'member cannot read another contact');denied(fn()=>(new Registry($db,'member'))->saveContact(null,0,'person','Unauthorized','',''),'member cannot create contacts');denied(fn()=>(new Finance($db,'member'))->accounts(),'member cannot load finances');denied(fn()=>(new Finance($db,'klaus'))->entries(),'press cannot load finances');denied(fn()=>(new Settings($db,'member'))->roles(),'member cannot read roles');
check(!(new AdmissionVotes($db,'admin'))->canVote(),'technical admin has no board vote');foreach(['paul','wilma','hartmut','klaus'] as $actor)check((new AdmissionVotes($db,$actor))->canVote(),$actor.' personal board vote');
$lists=new FreeTables($db,'admin');$sheet=$lists->create('Privater Test',['Aufgabe'],['text']);$lists->saveRow($sheet,'',0,['Intern']);denied(fn()=>(new FreeTables($db,'member'))->rows($sheet),'private list denied');$lists->share($sheet,'member','read',1);check(count((new FreeTables($db,'member'))->rows($sheet))===1,'explicit shared list visible');denied(fn()=>(new FreeTables($db,'member'))->saveRow($sheet,'',0,['No']),'read share cannot write');
$inv=new Inventory($db,'admin');$key=fn()=>bin2hex(random_bytes(16));$loc=$inv->saveLocation('',0,['name'=>'Private Testadresse','holder_id'=>$other],$key());$item=$inv->saveItem('',0,['code'=>'TEST','name'=>'Stühle','unit'=>'Stück','home_location'=>$loc,'responsible_id'=>$other,'unit_value'=>'40.00','value_note'=>'Synthetischer Wertbeleg','notes'=>'Private Notizen'],$key());
$inv->move($item,(int)$inv->item($item)['stock_version'],['kind'=>'receive','quantity'=>'5','location'=>$loc,'reason'=>'Synthetischer Zugang'],$key());$material=$inv->memberItems();denied(fn()=>(new Inventory($db,'member'))->memberItems(),'ordinary member cannot read material');denied(fn()=>(new Inventory($db,'member'))->loans(),'ordinary member cannot list own loans');denied(fn()=>(new Inventory($db,'member'))->whereabouts(['member'=>$own],true),'ordinary member cannot read own storage');check(count($material)===1&&(int)$material[0]['available']===5,'authorized inventory role sees material availability');check(array_keys($material[0])===['id','name','category','unit','content_quantity','content_unit','available','reserved','lent'],'material exposes no contacts locations values or notes');denied(fn()=>(new Inventory($db,'member'))->item($item),'full inventory detail denied');denied(fn()=>(new Inventory($db,'editor'))->memberItems(),'editor cannot read member material');
$db->exec("UPDATE actors SET active=0 WHERE id='member'");check(!(new WorkspaceAccess($db,'member'))->allows(['view'=>'minutes']),'inactive account rejected');denied(fn()=>(new Inventory($db,'member'))->memberItems(),'inactive member cannot read material');
$db->exec("UPDATE actors SET active=1,is_superuser=1 WHERE id='member'");$promoted=Permissions::actor($db,'member');check($promoted['finance_access']==='write'&&$promoted['members_access']==='write'&&$promoted['settings_access']===1,'explicit promoted member has technical superuser rights');check(!(new AdmissionVotes($db,'member'))->canVote(),'promotion never creates board office');check((new WorkspaceAccess($db,'member'))->allows(['view'=>'website','tab'=>'pages']),'promoted member edits website with same account');
// Navigation and direct routes must share the same defaults and disabled-account boundary.
check((new WorkspaceAccess($db,'klaus'))->allows(['view'=>'portal']),'default portal matches own-profile redirect');
check(!(new WorkspaceAccess($db,'editor'))->allows(['view'=>'portal']),'editor cannot enter default member portal');
$db->exec("INSERT INTO actors(id,club_id,role) VALUES('reader','a','member'),('disabled-binding','a','members')");
$readRole=$settings->saveRole('',0,['name'=>'Read audit']+array_replace($none,['members_access'=>'read','finance_access'=>'read','inventory_access'=>'read','documents_access'=>'read']));$settings->assignRole('reader',$readRole,0);
$readerAccess=new WorkspaceAccess($db,'reader');
foreach(['members','finance','documents','inventory'] as $view)check($readerAccess->allows(['view'=>$view]),'reader visible and direct route '.$view);
check(!$readerAccess->allows(['view'=>'members','tab'=>'archive']),'read-only role cannot enter member archive');
denied(fn()=>(new Registry($db,'reader'))->saveContact(null,0,'person','Unauthorized','',''),'member reader cannot write contact');
denied(fn()=>(new Finance($db,'reader'))->createAccount('Unauthorized','cash','0','2026-09-07'),'finance reader cannot create account');
denied(fn()=>(new Settings($db,'reader'))->save('tax',[],0),'finance reader cannot change tax settings');
denied(fn()=>(new Documents($db,'reader'))->upload('bad.xml','<x/>',['title'=>'Unauthorized','kind'=>'receipt','scope'=>'finance'],bin2hex(random_bytes(16))),'document reader cannot upload');
check((new \Kulturhus\Verein\InvoiceApprovals($db,'admin'))->canApprove(),'superuser may approve invoices');
check((new \Kulturhus\Verein\InvoiceApprovals($db,'hartmut'))->canApprove(),'checked active treasurer can approve');
check((new \Kulturhus\Verein\InvoiceApprovals($db,'wilma'))->canApprove(),'checked active board office can approve');
check(!(new \Kulturhus\Verein\InvoiceApprovals($db,'klaus'))->canApprove(),'secretary cannot approve finance invoices');
denied(fn()=>(new Registry($db,'foreign'))->contact($own),'foreign club cannot access contact by known identifier');
$account=(new Finance($db,'admin'))->createAccount('Synthetic private account','cash','0','2026-09-07');
$db->exec("UPDATE actors SET is_superuser=1 WHERE id='foreign'");check((new Finance($db,'foreign'))->canRead(),'foreign actor has finance rights in own club');
denied(fn()=>(new Finance($db,'foreign'))->account($account),'foreign club cannot access account by known identifier');
$db->exec("INSERT INTO processwire_identities(pw_user_id,actor_id,enabled) VALUES(99001,'disabled-binding',0)");
foreach(array_values($routes) as $route)check(!(new WorkspaceAccess($db,'disabled-binding'))->allows($route),'disabled identity denies '.$route['view']);
denied(fn()=>(new Finance($db,'disabled-binding'))->accounts(),'disabled binding blocks direct service');
// Even a malformed full role assignment cannot turn the editorial account into an internal account.
$db->prepare('INSERT INTO settings_role_assignments(club_id,actor_id,role_id,version) VALUES(?,?,?,?)')->execute(['a','editor',$readRole,1]);$db->exec("UPDATE actors SET is_superuser=1 WHERE id='editor'");
$editor=Permissions::actor($db,'editor');foreach(['members_access','finance_access','inventory_access','loans_access','documents_access','minutes_access'] as $field)check($editor[$field]==='none','editor trust boundary '.$field);
check(!$editor['settings_access'],'editor cannot gain settings through corrupt superuser flag');
check((new WorkspaceAccess($db,'editor'))->allows(['view'=>'website','tab'=>'pages']),'editor retains intended website access');
echo "$checks workspace access checks passed\n";
